SELECT analytics_order_facts.region, COUNT(DISTINCT analytics_order_facts.active_customer_id) AS active_customer_count FROM analytics_order_facts WHERE analytics_order_facts.year = 2022 AND analytics_order_facts.month = 2 AND analytics_order_facts.channel = 'online' AND analytics_order_facts.customer_segment = 'consumer' AND analytics_order_facts.payment_method = 'voucher' GROUP BY analytics_order_facts.region ORDER BY active_customer_count DESC, analytics_order_facts.region ASC LIMIT 12
